mapper.select:
select  from lab_task t
left join lab_member lm on lm.id=t.owner_id and lm.del_flag='0'
left join sys_user u on u.user_id=lm.user_id and u.del_flag='0'
where t.del_flag='0'
and t.id=#{id}and t.parent_id=#{parentId}
and t.goal_id=#{goalId}and t.milestone_id=#{milestoneId}
and t.task_level=#{taskLevel}
and t.period=#{period}
and t.biz_line=#{bizLine}
and t.task_type=#{taskType}
and t.owner_id=#{ownerId}and t.dept_id=#{deptId}
and t.workflow_status=#{workflowStatus}
and t.result_status=#{resultStatus}
and t.title like concat('%',#{title},'%')
${params.dataScope}
order by t.period desc,t.plan_date,t.id
